param([string]$OutputDirectory='Architecture/M180_Living_Shell_Route_Audit_2026-10-31/artifacts')
$ErrorActionPreference='Stop'
$root=Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path);$out=Join-Path $root $OutputDirectory
$bathRel='Architecture/Direction_D_BathFirst_Adjacency_Study_2026-10-27/study.json';$m179Rel='Architecture/M179_Pantry_Route_Clearance_Audit_2026-10-31/m179-study.json';$selectedRel='Architecture/Selected_Design_Iteration_2026-10-27/study.json'
foreach($r in @($bathRel,$m179Rel,$selectedRel)){if(-not(Test-Path (Join-Path $root $r) -PathType Leaf)){throw "Missing input $r"}}
if((Test-Path $out)-and @(Get-ChildItem $out -Force).Count-gt0){throw "Refusing to overwrite $out"};if(-not(Test-Path $out)){New-Item -ItemType Directory $out|Out-Null}
function Sha180($p){(Get-FileHash (Join-Path $root $p) -Algorithm SHA256).Hash.ToLowerInvariant()}
$bath=Get-Content (Join-Path $root $bathRel) -Raw|ConvertFrom-Json;$m179=Get-Content (Join-Path $root $m179Rel) -Raw|ConvertFrom-Json;$m173=Get-Content (Join-Path $root 'Architecture/Direction_D_Social_Route_Study_2026-10-27/study.json') -Raw|ConvertFrom-Json
$main=$bath.plans.main;$m01=@($main|Where-Object id -eq 'M-01')[0];$m04=@($main|Where-Object id -eq 'M-04')[0];$m05=@($main|Where-Object id -eq 'M-05')[0];$m02=@($main|Where-Object id -eq 'M-02')[0]
$ox=[double]$m02.x;$oy=[double]$m02.y;$shellW=[double]$bath.selection.main_shell[0];$shellD=[double]$bath.selection.main_shell[1]
$route=@([pscustomobject]@{x=19.5;y=10.0},[pscustomobject]@{x=11.25;y=10.0},[pscustomobject]@{x=11.25;y=14.5},[pscustomobject]@{x=9.5;y=14.5},[pscustomobject]@{x=9.5;y=22.5},[pscustomobject]@{x=8.5;y=22.5},[pscustomobject]@{x=8.5;y=27.5})
$localM01=[ordered]@{id='M01-living';x=([double]$m01.x-$ox);y=([double]$m01.y-$oy);w=[double]$m01.w;d=[double]$m01.d};$localM04=[ordered]@{id='M04-pantry';x=([double]$m04.x-$ox);y=([double]$m04.y-$oy);w=[double]$m04.w;d=[double]$m04.d};$localM05=[ordered]@{id='M05-entry';x=([double]$m05.x-$ox);y=([double]$m05.y-$oy);w=[double]$m05.w;d=[double]$m05.d}
$counter=[ordered]@{id='perimeter-run';x=0.0;y=0.75;w=2.0;d=12.5};$island=[ordered]@{id='island';x=5.5;y=3.0;w=4.0;d=8.0};$stools=[ordered]@{id='assumed-stools';x=5.5;y=11.0;w=4.0;d=2.0};$table=[ordered]@{id='table';x=3.0;y=17.5;w=5.0;d=3.0}
$chairs=@([ordered]@{id='south-chair-1';x=3.5;y=15.8333333333;w=1.5;d=1.6666666667},[ordered]@{id='south-chair-2';x=6.0;y=15.8333333333;w=1.5;d=1.6666666667},[ordered]@{id='west-chair-1';x=1.3333333333;y=17.5;w=1.6666666667;d=1.5},[ordered]@{id='west-chair-2';x=1.3333333333;y=19.0;w=1.6666666667;d=1.5})
$wall=[ordered]@{id='half-wall';x=13.0;y=0.0;w=0.5;d=7.0};$return=[ordered]@{id='wall-return';x=13.0;y=13.0;w=0.5;d=1.0};$porchWalls=@([ordered]@{id='porch-west-wall';x=-0.5;y=24.5;w=6.5;d=0.5},[ordered]@{id='porch-east-wall';x=11.0;y=24.5;w=0.5;d=0.5})
function Rects($p,$w){$r=New-Object System.Collections.Generic.List[object];for($i=0;$i-lt$p.Count-1;$i++){$a=$p[$i];$b=$p[$i+1];if([Math]::Abs($a.x-$b.x)-lt1e-6){$r.Add([ordered]@{id="route-$i";x=$a.x-$w/2;y=[Math]::Min($a.y,$b.y);w=$w;d=[Math]::Abs($b.y-$a.y)})}else{$r.Add([ordered]@{id="route-$i";x=[Math]::Min($a.x,$b.x);y=$a.y-$w/2;w=[Math]::Abs($b.x-$a.x);d=$w})};if($i-gt0){$r.Add([ordered]@{id="corner-$i";x=$a.x-$w/2;y=$a.y-$w/2;w=$w;d=$w})}};return $r.ToArray()}
function Intersect($a,$b){$dx=[Math]::Min($a.x+$a.w,$b.x+$b.w)-[Math]::Max($a.x,$b.x);$dy=[Math]::Min($a.y+$a.d,$b.y+$b.d)-[Math]::Max($a.y,$b.y);if($dx-gt1e-6-and$dy-gt1e-6){return [ordered]@{route=$a.id;obstacle=$b.id;area_sf=[Math]::Round($dx*$dy,5)}};return $null}
$rects=Rects $route 3.0;$obstacles=@($localM04)+@($localM05)+@($counter)+@($island)+@($stools)+@($table)+@($chairs)+@($wall)+@($return)+@($porchWalls);$hits=New-Object System.Collections.Generic.List[object]
foreach($r in $rects){foreach($o in $obstacles){$h=Intersect $r $o;if($null-ne$h){$hits.Add($h)}}}
$pantryGapIn=([double]$localM04.y-($route[3].y+1.5))*12
$checks=New-Object System.Collections.Generic.List[object];function Add180($id,$pass,$detail){$script:checks.Add([pscustomobject]@{id=$id;pass=[bool]$pass;detail=$detail})}
$oldStart=$m179.dogleg_route.centerline_ft[0];$oldStartInside=($oldStart.x-ge$localM01.x-and$oldStart.x-le($localM01.x+$localM01.w)-and$oldStart.y-ge$localM01.y-and$oldStart.y-le($localM01.y+$localM01.d))
$start=$route[0];$startInside=($start.x-ge$localM01.x-and$start.x-le($localM01.x+$localM01.w)-and$start.y-ge$localM01.y-and$start.y-le($localM01.y+$localM01.d))
$gap=[double]$m01.x-([double]$m02.x+13.5);$openCross=$route[0].y; $originHash=(Get-FileHash (Join-Path $root $selectedRel) -Algorithm SHA256).Hash.ToLowerInvariant()
Add180 'source_bathfirst_hash_current' ((Sha180 $bathRel)-eq([string]$m179.source_fingerprints_sha256.PSObject.Properties[$bathRel].Value)) 'Bath-first room blocks match the M179-bound source hash.'
Add180 'prior_m179_origin_not_in_living' (-not$oldStartInside) 'M179 origin is outside the M-01 living block; this gap is now explicit.'
Add180 'revised_origin_inside_living' $startInside 'Revised route begins inside M-01 in source-local coordinates.'
Add180 'kitchen_living_gap_quantified' ([Math]::Abs($gap-4.3333333333)-lt0.001) 'Candidate M-02 ends 4 ft 4 in west of the M-01 block; the route crosses this unassigned open band.'
Add180 'opening_cross_section_fits' ($openCross-1.5-ge7-and$openCross+1.5-le13) '36 in route crosses the 6 ft half-wall opening with 18 in margins.'
Add180 'route_avoids_adjacent_and_furniture_blocks' ($hits.Count-eq0) 'Dogleg avoids M-04, M-05, kitchen furniture, dining furniture and modeled wall segments.'
Add180 'route_reaches_nominal_porch_door' ($route[-1].x-ge6-and$route[-1].x-le11-and[math]::Abs($route[-1].y-27.5)-lt0.001) 'Centerline crosses the nominal door span and extends 3 ft into the porch.'
Add180 'porch_test_within_shell' ($ox-0.5-ge0-and$ox+11.5-le$shellW-and$oy+34.5-le$shellD) 'Translated porch test rectangle fits within the 40 x 42 ft comparison shell.'
Add180 'route_corridor_within_shell' ($ox+21-le$shellW-and$oy+29-le$shellD-and$ox+7.0-ge0-and$oy+7.0-ge0) 'Full 36 in route corridor bounding extent remains inside the comparison shell.'
Add180 'pantry_connector_y_gap' (([Math]::Abs(([double]$localM04.y)-16.5)-lt0.001)-and([Math]::Abs($pantryGapIn-6)-lt0.001)) 'Route corridor ends at local y=16 ft; pantry begins at y=16.5 ft, yielding a derived 6 in separation.'
Add180 'selected_d_unchanged' ($originHash-eq'516d6d17e5b6ed6c8ec8cbf7a925cc67c5cc1c0ada194c22ea3fa124e2bb72bb') 'Selected-D source fingerprint remains the verified baseline.'
Add180 'm06_b_unassigned' ($m173.geometry.m06_window_b_remains_unassigned-eq$true) 'M-06/B remains unassigned.'
$passed=@($checks|Where-Object pass).Count;$status='fail';if($passed-eq$checks.Count){$status='pass'}
$porchGlobal=@([double]($ox-0.5),[double]($oy+24.5),12.0,10.0)
$report=[ordered]@{schema='forever-home-m180-living-shell-route-v1';status='unapproved source-coordinate route overlay';source_fingerprints_sha256=[ordered]@{$bathRel=(Sha180 $bathRel);$m179Rel=(Sha180 $m179Rel);$selectedRel=$originHash};shell_ft=@($shellW,$shellD);coordinate_origin_source_ft=@($ox,$oy);room_blocks=[ordered]@{M01_local_rect_ft=@($localM01.x,$localM01.y,$localM01.w,$localM01.d);M02_candidate_rect_local_ft=@(0,0,13.5,14);M02_to_M01_open_gap_ft=$gap;M04_local_rect_ft=@($localM04.x,$localM04.y,$localM04.w,$localM04.d);M05_local_rect_ft=@($localM05.x,$localM05.y,$localM05.w,$localM05.d)};prior_m179_origin_local_ft=$oldStart;revised_route=[ordered]@{centerline_local_ft=$route;width_in=36;rectangles_local_ft=$rects;obstacle_hits=$hits.ToArray();opening_centerline_y_ft=$openCross;unassigned_kitchen_living_gap_ft=$gap;pantry_connector_clearance_in=$pantryGapIn;porch_global_rect_ft=$porchGlobal};conclusion='Extending the M179 route origin into M-01 makes the living-to-porch route continuous across the source-coordinate overlay. It crosses a 4 ft 4 in unassigned band between the reduced M-02 candidate and M-01. The dogleg clears M-04 and M-05 rectangles and the modeled furniture/walls; the porch remains within the 40 x 42 ft test shell. No physical opening, shell wall or room assignment is validated.';limitations=@('Bath-first blocks and M02 candidate geometry are unapproved; source-shell arithmetic is schematic.','The 4 ft 4 in M02-to-M01 band is unassigned and needs a room/circulation decision.','Porch and route are only coordinate rectangles; exterior connection, wall construction, thresholds, door swing/clear width and physical passage are not modeled.','Stool, chair movement and appliance-open envelopes are not validated.','No Revit/IFC change or M-06/B placement is included; no accessibility/code/structural/construction approval is established.')}
$cr=[ordered]@{status=$status;passed=$passed;total=$checks.Count;checks=$checks.ToArray()}
$report|ConvertTo-Json -Depth 80|Set-Content (Join-Path $out 'm180-study.json') -Encoding UTF8;$cr|ConvertTo-Json -Depth 50|Set-Content (Join-Path $out 'm180-checks.json') -Encoding UTF8;$checks.ToArray()|Export-Csv (Join-Path $out 'm180-checks.csv') -NoTypeInformation -Encoding UTF8
Write-Output ("M180: {0}/{1}; old living origin inside={2}; revised inside={3}; M02-M01 gap={4:F2} ft; obstacle hits={5}." -f $passed,$checks.Count,$oldStartInside,$startInside,$gap,$hits.Count)
if($passed-ne$checks.Count){exit 1}
